# Loop over input items and add a new field called 'my_new_field' to the JSON of each one
output = []

for item in _items:
    data = item["json"]

    title = data.get("title", "")
    date = data.get("date", "")
    content = data.get("content", "")
    link = data.get("link", "")
    item_type = data.get("type", "")

    # Skip empty/null records
    if not title or not content:
        continue

    text = f"""
Title: {title}
Date: {date}
Type: {item_type}

Content:
{content}
""".strip()

    output.append({
        "json": {
            "text": text,
            "title": title,
            "date": date,
            "type": item_type,
            "link": link
        }
    })

return output

