# Get all embedding values returned by Hugging Face
output = []

dimension = 384

# Collect all embedding values
values = []

for item in _items:
    value = item["json"]

    if isinstance(value, (int, float)):
        values.append(value)

# Create one vector for every chunk
for i in range(0, len(values), dimension):

    vector = values[i:i + dimension]

    if len(vector) != dimension:
        continue

    output.append({
        "json": {
            "embedding": vector
        }
    })

return output
